/* Multiplication by powers of 2 (x * 2^N) */
int mul_pow2(int x, int n) {
    return x << n;
}

/* Division by powers of 2 (x / 2^N) */
unsigned int div_pow2_unsigned(unsigned int x, int n) {
    return x >> n;
}

/* Modulo by powers of 2 (x % 2^N) */
int mod_pow2(int x, int n) {
    return x & ((1 << n) - 1);
}

/* Check if power of 2 */
bool is_pow2(unsigned int n) {
    return (n > 0) && ((n & (n - 1)) == 0);
}

/* Swap values without temp variable (XOR swap) */
void swap_xor(int* a, int* b) {
    *a ^= *b;
    *b ^= *a;
    *a ^= *b;
}

/* Extract sign bit (assuming 32-bit int) */
int get_sign(int x) {
    return x >> 31;
}

/* Multiply by 5 (x * 4 + x) */
int mul_by_5(int x) {
    return (x << 2) + x;
}

/* Multiply by 7 (x * 8 - x) */
int mul_by_7(int x) {
    return (x << 3) - x;
}
